=head2 Google::Cloud::Visionai::V1alpha1::Warehouse::AnnotationMatchingResult

Stores the criteria-annotation matching results for each search result item.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->criteria() >> / C<< $msg->criteria($value) >>

Type: C<Message> (L<Google::Cloud::Visionai::V1alpha1::Warehouse::Criteria>)

